mapper.update:
update user_referral
set reward_status = 'REWARDED', reward_amount = #{rewardAmount}, reward_time = #{rewardTime}, reward_operator_user_id = #{rewardOperatorUserId}
where id = #{id} and (reward_status = 'PENDING' or reward_status is null or reward_status = '')

mapper.select:


    and inviter_user_id = #{inviterUserId}
    and invitee_user_id = #{inviteeUserId}
    and invite_code = #{inviteCode}

order by create_time desc

select ur.id as id, ur.invitee_user_id as user_id, ui_ee.user_name as user_name, ui_ee.phone as phone, ui_ee.avatar_url as avatar_url, ur.inviter_user_id as inviter_user_id, ui_er.user_name as inviter_user_name, ui_er.phone as inviter_phone, ur.invite_code as invite_code, ur.reward_status as reward_status, ur.reward_amount as reward_amount, ur.reward_time as reward_time, ur.create_time as create_time from user_referral ur left join user_info ui_ee on ur.invitee_user_id = ui_ee.user_id left join user_info ui_er on ur.inviter_user_id = ui_er.user_id where ur.inviter_user_id in
#{inviterUserId}
order by ur.create_time desc
